165	func (s *service) listModelsFromSnapshot(ctx context.Context, sc ServiceConfig, cat *modelcatalog.Catalog, snapshot modelsnapshot.ModelSnapshot, filter ModelFilter) []ModelInfo {
166		defaultProviderName := sc.DefaultProviderName()
167		entries := make(map[string]ServiceProviderEntry, len(sc.ProviderNames()))
168		for _, name := range sc.ProviderNames() {
169			if filter.Provider != "" && filter.Provider != name {
170				continue
171			}
172			entry, ok := sc.Provider(name)
173			if !ok {
174				continue
175			}
176			entries[name] = entry
177		}
178	
179		modelsByProvider := make(map[string][]modelsnapshot.KnownModel, len(snapshot.Models))
180		for _, model := range snapshot.Models {
181			if filter.Provider != "" && filter.Provider != model.Provider {
182				continue
183			}
184			if _, ok := entries[model.Provider]; !ok {
185				continue
186			}
187			modelsByProvider[model.Provider] = append(modelsByProvider[model.Provider], model)
188		}
189	
190		rankByEndpoint := make(map[string]int, len(snapshot.Models))
191		out := make([]ModelInfo, 0, len(snapshot.Models))
192		for _, providerName := range sc.ProviderNames() {
193			if filter.Provider != "" && filter.Provider != providerName {
194				continue
195			}
196			entry, ok := entries[providerName]
197			if !ok {
198				continue
199			}
200			for _, model := range modelsByProvider[providerName] {
201				normalizedModel := model
202				normalizedModel.ServerInstance = serverinstance.Normalize(model.EndpointBaseURL, model.ServerInstance)
203				rankKey := strings.Join([]string{normalizedModel.Provider, normalizedModel.EndpointName, normalizedModel.EndpointBaseURL, normalizedModel.ServerInstance}, "\x00")
204				rank := rankByEndpoint[rankKey]
205				rankByEndpoint[rankKey] = rank + 1
206				out = append(out, s.modelInfoFromSnapshotModel(ctx, providerName, entry, defaultProviderName, cat, normalizedModel, rank))
207			}
208		}
209		return out
210	}
