560	// shouldEscalateOnError gates ladder escalation to "no eligible candidate"
561	// errors. Hard caller-pin conflicts (ErrHarnessModelIncompatible,
562	// ErrPolicyRequirementUnsatisfied) are surfaced as-is — escalating past an explicit
563	// pin would silently change the caller's intent.
564	func shouldEscalateOnError(err error) bool {
565		var modelConstraintAmbiguous *ErrModelConstraintAmbiguous
566		if errors.As(err, &modelConstraintAmbiguous) {
567			return false
568		}
569		var modelConstraintNoMatch *ErrModelConstraintNoMatch
570		if errors.As(err, &modelConstraintNoMatch) {
571			return false
572		}
573		var modelErr *routing.ErrHarnessModelIncompatible
574		if errors.As(err, &modelErr) {
575			return false
576		}
577		var pinErr *routing.ErrUnsatisfiablePin
578		if errors.As(err, &pinErr) {
579			return false
580		}
581		var policyErr *routing.ErrPolicyRequirementUnsatisfied
582		if errors.As(err, &policyErr) {
583			return false
584		}
585		return routehealth.ShouldEscalateOnError(err)
586	}
